package com.aitu.lms.app;
import com.aitu.lms.domain.*; import com.aitu.lms.observer.*; import com.aitu.lms.integration.*; import com.aitu.lms.visitor.*;
public final class UniversityLms implements AutoCloseable {
 private final ThreadSafeSubject subject; private final GradeSource grades; private final DeadlineSource deadlines; private final Faculty faculty;
 public UniversityLms(int threads){subject=new ThreadSafeSubject(threads); grades=new GradeSource(subject); deadlines=new DeadlineSource(subject); faculty=buildTree();}
 private Faculty buildTree(){var f=new Faculty("School of Software Engineering");var p=new Program("Software Engineering");var c=new Course("Algorithms",5);c.add(new Lecture("Graphs",4));c.add(new Lab("Union Find",3));c.add(new Exam("Final Exam",2));c.add(new Student("S001","Aruzhan",3.4));p.add(c);var c2=new Course("Operating Systems",4);c2.add(new Lecture("Processes",4));c2.add(new Lab("Linux",3));c2.add(new Exam("OS Final",2));c2.add(new Student("S002","Nurasyl",3.1));p.add(c2);f.add(p);return f;}
 public void installDefaultListeners(){subject.subscribe(EventType.GRADE_CHANGED,new RecordingListener("student"));subject.subscribe(EventType.GRADE_CHANGED,new RecordingListener("parent"));subject.subscribe(EventType.GRADE_CHANGED,new RecordingListener("advisor"));subject.subscribe(EventType.GRADE_CHANGED,new GpaTracker());subject.subscribe(EventType.DEADLINE_UPDATED,new RecordingListener("deadline-tracker"));var aggregator=new AggregatingListener(subject);subject.subscribe(EventType.GRADE_CHANGED,aggregator);subject.subscribe(EventType.GPA_UPDATED,new RecordingListener("gpa-report"));subject.subscribe(EventType.ALERT,new AlertInspectionListener(subject,faculty));}
 public void gradeChanged(String id,String message){grades.gradeChanged(id,message);} public void deadlineUpdated(String id,String message){deadlines.deadlineUpdated(id,message);} public void alert(String id,String message){subject.publish(new Event(EventType.ALERT,id,message,java.time.Instant.now()));} public Faculty faculty(){return faculty;} public ThreadSafeSubject subject(){return subject;} public void close(){subject.shutdownGracefully();}
 public static void main(String[] args){try(var app=new UniversityLms(4)){app.installDefaultListeners();app.gradeChanged("S001","Algorithms grade updated");app.deadlineUpdated("S001","OS deadline tomorrow");app.alert("S001","GPA threshold alert");}}
}
